import React, { useState, useEffect, useRef } from 'react';
import { StatusBar, View, Text, ScrollView, TextInput, Pressable, StyleSheet, KeyboardAvoidingView, Platform } from 'react-native';
import * as Speech from 'expo-speech';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { levels, scenarios, mockReply, exercise, splitSentences, hintForWord } from './model';

/* eslint-disable react-hooks/refs -- Speech callbacks are only invoked by Pressable event handlers; the shared button helper obscures that from this rule. */
// Initial mobile prototype: listening uses device TTS; role-play voice and chat are simulated.
export default function App() {
 const [tab,setTab]=useState('Speak'),[level,setLevel]=useState('A2');
 const [scene,setScene]=useState(null),[messages,setMessages]=useState([]),[draft,setDraft]=useState('');
 const [saved,setSaved]=useState([]),[storageReady,setStorageReady]=useState(false),[feedback,setFeedback]=useState(''),[recap,setRecap]=useState(false);
 const [variant,setVariant]=useState(0),[answer,setAnswer]=useState(null),[checked,setChecked]=useState(false);
 const [revealed,setRevealed]=useState(false),[heard,setHeard]=useState(false),[audioStatus,setAudioStatus]=useState('Listen before answering.'),[slow,setSlow]=useState(true);
 const [activeSentence,setActiveSentence]=useState(-1),[wordHint,setWordHint]=useState(null);
 const playbackRun=useRef(0);
 const item=exercise(level,variant);
 const sentences=splitSentences(item.text);
 useEffect(()=>{let mounted=true;AsyncStorage.getItem('norsk-rom.saved-phrases').then(raw=>{if(mounted&&raw){const parsed=JSON.parse(raw);if(Array.isArray(parsed))setSaved(parsed);}}).catch(()=>{}).finally(()=>{if(mounted)setStorageReady(true);});return()=>{mounted=false;};},[]);
 useEffect(()=>{if(storageReady)AsyncStorage.setItem('norsk-rom.saved-phrases',JSON.stringify(saved)).catch(()=>setFeedback('Could not save phrases on this device.'));},[saved,storageReady]);
 useEffect(()=>()=>{playbackRun.current++;Speech.stop();},[]);
 function stopPlayback(){playbackRun.current++;Speech.stop();}
 function resetListening(){stopPlayback();setRevealed(false);setHeard(false);setActiveSentence(-1);setWordHint(null);setAudioStatus('Listen before answering.');}
 async function listen(startAt=0){try{stopPlayback();const run=playbackRun.current;const voices=await Speech.getAvailableVoicesAsync();if(playbackRun.current!==run)return;const voice=voices.find(v=>/^(nb|no|nn)(-|_|$)/i.test(v.language));if(!voice){setAudioStatus('No Norwegian voice available. Enable one in your device settings.');return;}if(startAt>=sentences.length){setAudioStatus('No sentence to play.');return;}setHeard(false);setRevealed(true);setActiveSentence(startAt);setAudioStatus('Playing sentence by sentence…');const speakSentence=index=>{if(playbackRun.current!==run)return;if(index>=sentences.length){setHeard(true);setAudioStatus('Playback finished. Now answer or replay.');return;}setActiveSentence(index);Speech.speak(sentences[index],{language:voice.language,voice:voice.identifier,rate:slow?0.8:1,onDone:()=>speakSentence(index+1),onStopped:()=>{},onError:()=>{if(playbackRun.current===run)setAudioStatus('Playback failed. Try again.');}});};speakSentence(startAt);}catch{setAudioStatus('Speech is unavailable on this device.');}}

 function start(s){setScene(s);setMessages([{who:'Partner',text:s.opening}]);setDraft('');setFeedback('');setRecap(false);}
 function send(text){if(!text.trim())return;const result=mockReply(scene,text,messages.filter(m=>m.who==='You').length);setMessages([...messages,{who:'You',text:text.trim()},{who:'Partner',text:result.reply}]);setFeedback(result.correction?`${result.correction.before} → ${result.correction.after}\n${result.correction.why}`:'No fixture correction triggered. Other grammar and pronunciation are not evaluated.');setDraft('');setRecap(false);}
 function save(p){setSaved(current=>current.some(x=>x[0]===p[0])?current.filter(x=>x[0]!==p[0]):[...current,p]);}
 const button=(label,onPress,secondary=false,disabled=false)=><Pressable accessibilityRole="button" accessibilityState={{disabled}} disabled={disabled} onPress={onPress} style={[styles.button,secondary&&styles.secondary,disabled&&{opacity:.45}]}><Text style={[styles.buttonText,secondary&&{color:colors.ink}]}>{label}</Text></Pressable>;
 const phrase=p=><View key={p[0]} style={styles.phrase}><Pressable accessibilityRole="button" accessibilityLabel={`Use phrase: ${p[0]}`} style={{flex:1}} onPress={()=>{if(scene){setDraft(p[0]);setTab('Speak');}else{setFeedback('Start a scenario to use a saved phrase.');}}}><Text style={styles.body}>{p[0]}</Text><Text style={styles.small}>{p[1]}</Text></Pressable><Pressable accessibilityRole="button" accessibilityLabel={`Toggle saved phrase: ${p[0]}`} onPress={()=>save(p)} style={styles.save}><Text style={styles.body}>{saved.some(x=>x[0]===p[0])?'✓':'+'}</Text></Pressable></View>;
 return <KeyboardAvoidingView style={styles.root} behavior={Platform.OS==='ios'?'padding':undefined}>
 <StatusBar barStyle="dark-content"/>
 <ScrollView keyboardShouldPersistTaps="handled" contentContainerStyle={styles.page}>
 <View style={styles.top}><Text style={styles.brand}>◉ norsk rom</Text><Text style={styles.eyebrow}>MOCK DEMO</Text></View>
 <Text style={styles.eyebrow}>A LITTLE PRACTICE. A LITTLE CLOSER.</Text><Text style={styles.title}>Find your words.</Text><Text style={styles.small}>Everyday Norwegian, one conversation at a time.</Text>
 <View style={styles.wrap}>{levels.map(l=><Pressable key={l} accessibilityRole="button" accessibilityState={{selected:level===l}} onPress={()=>{setLevel(l);setAnswer(null);setChecked(false);resetListening();}} style={[styles.pill,level===l&&styles.selected]}><Text style={{color:level===l?'white':colors.ink}}>{l}</Text></Pressable>)}</View>
 <View style={styles.wrap}>{['Speak','Listen','Saved'].map(t=><Pressable key={t} accessibilityRole="tab" accessibilityState={{selected:tab===t}} onPress={()=>{setTab(t);resetListening();}} style={[styles.tab,tab===t&&{borderBottomColor:colors.ink}]}><Text style={styles.body}>{t}</Text></Pressable>)}</View>
 {tab==='Speak'&&!scene&&<><View style={styles.hero}><Text style={styles.light}>ROOM TO SPEAK</Text><Text style={[styles.title,{color:colors.paper}]}>Small moments. Real confidence.</Text><Text style={styles.light}>Choose a scene. Keep useful phrases close. Learn by trying.</Text></View>{scenarios.map(s=><View style={styles.card} key={s.id}><Text style={styles.eyebrow}>{s.place}</Text><Text style={styles.heading}>{s.icon} {s.short}</Text><Text style={styles.body}>{s.goal}</Text>{button('Start conversation ↗',()=>start(s))}</View>)}</>}
 {tab==='Speak'&&scene&&<>
 {button('← All scenarios',()=>{setScene(null);setFeedback('');},true)}
 <Text style={styles.heading}>{scene.short}</Text><Text style={styles.small}>Scripted partner · level selection changes listening samples only in this demo.</Text>
 <View style={styles.card}><Text style={styles.eyebrow}>YOUR CONVERSATION TOOLKIT</Text>{scene.phrases.map(phrase)}</View>
 {messages.map((m,i)=><View key={i} style={[styles.bubble,m.who==='You'&&styles.user]}><Text style={[styles.eyebrow,m.who==='You'&&styles.light]}>{m.who}</Text><Text style={[styles.body,m.who==='You'&&styles.light]}>{m.text}</Text></View>)}
 {!!feedback&&<Text accessibilityLiveRegion="polite" style={styles.feedback}>{feedback}</Text>}
 <TextInput accessibilityLabel="Your Norwegian reply" style={styles.input} value={draft} onChangeText={setDraft} placeholder="Skriv på norsk…" placeholderTextColor="#67766b" maxLength={500} multiline/>
 {button('Send reply',()=>send(draft),false,!draft.trim())}
 {button('Try a simulated voice turn',()=>send(scene.phrases[0][0]),true)}
 {button('Insert grammar example',()=>setDraft('Jeg er gå på kafé.'),true)}
 <Text style={styles.small}>No microphone or speech models are connected. Simulated voice inserts a predefined phrase.</Text>
 {button('Finish & review',()=>setRecap(true),true)}
 {recap&&<View style={styles.card}><Text style={styles.heading}>Practice recap</Text><Text style={styles.body}>{messages.filter(m=>m.who==='You').length} replies sent. Save an expression and try it again tomorrow.</Text><Text style={styles.small}>Pronunciation not assessed. No proficiency score calculated.</Text></View>}
 </>}
 {tab==='Listen'&&<><View style={styles.card}><Text style={styles.eyebrow}>EVERYDAY NORWAY · {level}</Text><Text style={styles.heading}>{item.title}</Text><Text style={styles.small}>{item.source}</Text>{button('▶ Play full sample',()=>listen(0))}{button('↻ Replay current sentence',()=>listen(Math.max(activeSentence,0)),true)}{button('Stop playback',()=>{stopPlayback();setActiveSentence(-1);setAudioStatus('Playback stopped.');},true)}{button(slow?'Speed: slow · 0.8×':'Speed: normal · 1×',()=>setSlow(!slow),true)}<Text accessibilityLiveRegion="polite" style={styles.small}>{audioStatus}</Text>{button(revealed?'Hide transcript':'Reveal transcript · help',()=>setRevealed(!revealed),true)}{revealed&&<View style={styles.transcript}>{sentences.map((sentence,i)=><Text key={`${i}-${sentence}`} style={[styles.transcriptSentence,activeSentence===i&&styles.activeSentence]}>{sentence.split(/(\s+)/).map((part,j)=>/\s+/.test(part)?part:<Text key={j} onPress={()=>{const hint=hintForWord(part);setWordHint({word:part,meaning:hint});}} style={styles.transcriptWord}>{part}</Text>)}</Text>)}<Text style={styles.small}>Tap a word for its built-in English hint. The highlight follows device speech sentence by sentence.</Text></View>}{wordHint&&<View style={styles.hint}><Text style={styles.body}>{wordHint.word} — {wordHint.meaning??'No offline hint for this word yet.'}</Text><Pressable accessibilityRole="button" onPress={()=>setWordHint(null)}><Text style={styles.small}>Dismiss</Text></Pressable></View>}<Text style={styles.small}>{item.note}</Text>{button('Try another sample ↻',()=>{setVariant(variant+1);setAnswer(null);setChecked(false);resetListening();})}<Text style={styles.small}>Two fictional listening scripts per level, spoken with a Norwegian device voice. No live programme imports or question generation.</Text></View><View style={styles.card}><Text style={styles.heading}>{item.question}</Text>{item.options.map((option,i)=><Pressable key={option} accessibilityRole="button" accessibilityState={{selected:answer===i}} onPress={()=>{setAnswer(i);setChecked(false);}} style={[styles.option,answer===i&&{backgroundColor:colors.lime}]}><Text style={styles.body}>{option}</Text></Pressable>)}{button('Check answer',()=>setChecked(true),false,answer===null||!heard)}<Text style={styles.small}>After listening, repeat one sentence and retell the clip aloud. Speech is not recorded or assessed.</Text>{checked&&<Text accessibilityLiveRegion="polite" style={styles.feedback}>{answer===item.answer?'Riktig! ':'Not quite. '}{item.explanation}</Text>}</View></>}
 {tab==='Saved'&&<View style={styles.card}><Text style={styles.heading}>Words worth keeping.</Text><Text style={styles.small}>Saved privately on this device.</Text>{saved.length?saved.map(phrase):<Text style={styles.body}>Save expressions with + during a role-play.</Text>}{!scene&&!!saved.length&&<Text style={styles.small}>Start a scenario to use a saved expression.</Text>}</View>}
 <Text style={[styles.small,{marginVertical:24}]}>Bokmål · English explanations · All content is fictional</Text>
 </ScrollView></KeyboardAvoidingView>;
}
const colors={ink:'#174d43',paper:'#f7f6ef',lime:'#d8ed9f',line:'#dce1d6'};
const styles=StyleSheet.create({root:{flex:1,backgroundColor:colors.paper},page:{padding:22,paddingTop:60,paddingBottom:45,maxWidth:700,width:'100%',alignSelf:'center'},top:{flexDirection:'row',justifyContent:'space-between',alignItems:'center',marginBottom:38},brand:{fontSize:25,fontWeight:'800',color:colors.ink},title:{fontFamily:Platform.OS==='ios'?'Georgia':'serif',fontSize:43,lineHeight:49,color:colors.ink,marginVertical:12},heading:{fontSize:24,fontWeight:'600',color:colors.ink,marginVertical:12},body:{fontSize:16,lineHeight:25,color:colors.ink},small:{fontSize:12,lineHeight:20,color:'#64736a'},eyebrow:{fontSize:10,letterSpacing:1.2,fontWeight:'700',color:colors.ink},light:{color:'#f7f6ef',lineHeight:24},wrap:{flexDirection:'row',flexWrap:'wrap',gap:8,marginVertical:14},pill:{paddingVertical:12,paddingHorizontal:14,borderRadius:22,borderWidth:1,borderColor:colors.line},selected:{backgroundColor:colors.ink},tab:{flex:1,padding:15,borderBottomWidth:2,borderBottomColor:'transparent',alignItems:'center'},hero:{backgroundColor:colors.ink,padding:26,borderRadius:24,marginBottom:15},card:{backgroundColor:'#fffef9',padding:22,borderRadius:20,borderWidth:1,borderColor:colors.line,marginVertical:10},button:{padding:16,borderRadius:13,backgroundColor:colors.ink,alignItems:'center',marginTop:12,minHeight:48},buttonText:{color:'white',fontWeight:'700',fontSize:14},secondary:{backgroundColor:'#e9eddf'},phrase:{flexDirection:'row',alignItems:'center',gap:10,paddingVertical:13,borderBottomWidth:1,borderBottomColor:colors.line},save:{width:44,height:44,alignItems:'center',justifyContent:'center',backgroundColor:'#e9eddf',borderRadius:22},bubble:{padding:17,borderRadius:18,backgroundColor:'#e9eddf',marginVertical:7,maxWidth:'94%',alignSelf:'flex-start'},user:{backgroundColor:colors.ink,alignSelf:'flex-end'},feedback:{padding:16,backgroundColor:'#fff0db',borderRadius:12,color:colors.ink,lineHeight:23,marginVertical:12},input:{backgroundColor:'white',borderWidth:1,borderColor:colors.line,borderRadius:12,padding:16,fontSize:16,color:colors.ink,minHeight:55,marginTop:16},option:{padding:16,borderWidth:1,borderColor:colors.line,borderRadius:12,marginVertical:5},transcript:{marginTop:14,padding:12,backgroundColor:'#f5f4ec',borderRadius:12},transcriptSentence:{fontSize:19,lineHeight:34,color:colors.ink,padding:8,borderRadius:8,marginBottom:5},activeSentence:{backgroundColor:colors.lime},transcriptWord:{color:colors.ink},hint:{padding:14,backgroundColor:'#fff0db',borderRadius:12,marginTop:12}});
